\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{hyperref}
\hypersetup{colorlinks=false}
\pagestyle{empty}

% ═══ Dark Tech Color Theme ═══
\definecolor{bgposter}{HTML}{080C1A}
\definecolor{bgcard}{HTML}{0F1428}
\definecolor{bgcard2}{HTML}{111832}
\definecolor{bgcard3}{HTML}{0E1A2D}
\definecolor{primary}{HTML}{3B82F6}
\definecolor{secondary}{HTML}{14B8A6}
\definecolor{accent}{HTML}{F59E0B}
\definecolor{textwhite}{HTML}{E2E8F0}
\definecolor{textgray}{HTML}{94A3B8}
\definecolor{statbg}{HTML}{1A2240}
\definecolor{titleruleblue}{HTML}{2563EB}
\definecolor{titleruleteal}{HTML}{0D9488}
\definecolor{titleruleamber}{HTML}{D97706}
\definecolor{cardbluebg}{HTML}{0D1B3E}
\definecolor{cardtealbg}{HTML}{0A1F20}
\definecolor{cardamberbg}{HTML}{1C160A}

\pagecolor{bgposter}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=28pt, itemsep=10pt, parsep=4pt, topsep=4pt,
  label={\color{primary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=28pt, itemsep=10pt, parsep=4pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card Styles (left accent stripe, dark backgrounds) ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbluebg,
    borderline west={5pt}{0pt}{primary},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=bgcard,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={primary!40},
    valign=top, drop shadow={opacity=0.25, shadow={2pt}{-2pt}{black!70}},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardtealbg,
    borderline west={5pt}{0pt}{secondary},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bgcard,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={secondary!40},
    valign=top, drop shadow={opacity=0.25, shadow={2pt}{-2pt}{black!70}},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardamberbg,
    borderline west={5pt}{0pt}{accent},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bgcard,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.25, shadow={2pt}{-2pt}{black!70}},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!bgposter,
    borderline west={6pt}{0pt}{primary},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{textwhite},
    coltitle=textwhite, colbacktitle=primary!60!bgposter,
    toptitle=8pt, bottomtitle=8pt,
    valign=top, drop shadow={opacity=0.30, shadow={3pt}{-3pt}{black!80}},
  },
}

% ── Dark statbox style ──
\newenvironment{darkstatbox}[1]{%
  \begin{tcolorbox}[
    enhanced, arc=0pt, boxrule=0pt, colback=statbg,
    left=12pt, right=12pt, top=16pt, bottom=16pt,
    halign=center, valign=center,
    borderline north={0.5pt}{0pt}{#1!30},
    borderline south={0.5pt}{0pt}{#1!30},
    drop shadow={opacity=0.20, shadow={2pt}{-2pt}{black!60}},
  ]
}{%
  \end{tcolorbox}%
}

% Hyperlink coloring
\definecolor{linkblue}{HTML}{60A5FA}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════════════════════════
% TITLE BAR (rows 0-5, span=3)
% ══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgposter, colframe=bgposter, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=20pt, bottom=16pt,
  halign=center, valign=center,
  borderline south={8pt}{0pt}{primary},
  drop shadow={opacity=0.30, shadow={0pt}{-4pt}{black!80}},
]{name=title, column=1, span=3, between=top and row5}{
  {\fontsize{72}{86}\selectfont\bfseries\color{primary} Aider LLM Polyglot}\\[8pt]
  {\fontsize{72}{86}\selectfont\bfseries\color{textwhite} Coding Leaderboard 2025}\\[14pt]
  {\fontsize{36}{44}\selectfont\color{textgray}
    Benchmarking 15 Large Language Models on Autonomous Code Editing Across 6 Programming Languages}\\[10pt]
  {\fontsize{26}{32}\selectfont\color{primary!70} aider.chat \hspace{8pt}\color{textgray}| \hspace{8pt}\color{primary!70} 225 Exercism Exercises \hspace{8pt}\color{textgray}| \hspace{8pt}\color{primary!70} C++ \, Go \, Java \, JavaScript \, Python \, Rust}
}

% ══════════════════════════════════════════════════════════════
% HERO METRICS (rows 5-7, span=3)
% ══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgcard, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=10pt, bottom=10pt,
  valign=center,
]{name=stats, column=1, span=3, between=row5 and row7}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \begin{darkstatbox}{primary}
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} 88.0\%}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textgray} Top Accuracy}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{primary!60} GPT-5 (high reasoning)}
    \end{darkstatbox}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \begin{darkstatbox}{secondary}
      {\fontsize{60}{72}\selectfont\bfseries\color{secondary} 225}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textgray} Coding Exercises}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{secondary!60} Across 6 Programming Languages}
    \end{darkstatbox}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \begin{darkstatbox}{accent}
      {\fontsize{60}{72}\selectfont\bfseries\color{accent} 30+}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textgray} Models Benchmarked}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{accent!60} OpenAI \, Anthropic \, Google \, DeepSeek}
    \end{darkstatbox}
  \end{minipage}
}

% ══════════════════════════════════════════════════════════════
% COLUMN 1: ABOUT + COST VS ACCURACY (rows 7-18)
% ══════════════════════════════════════════════════════════════
\posterbox[bluecard, title={About the Benchmark}
]{name=about, column=1, between=row7 and row11}{
  \fontsize{28}{36}\selectfont
  \begin{itemize}[itemsep=14pt]
    \item Aider is an AI pair-programming tool that evaluates LLMs on {\color{primary}\bfseries autonomous code editing}
    \item Models must produce correct code edits {\color{primary}\bfseries without any human intervention}
    \item Each model is tested on {\color{primary}\bfseries 225 Exercism coding challenges}
    \item {\color{primary}\bfseries Two attempts} allowed per exercise; pass = all tests green
    \item Primary metric: {\color{primary}\bfseries percent correct} — share of exercises passed
    \item Secondary: cost, edit format compliance, syntax errors
  \end{itemize}
}

\posterbox[ambercard, title={Cost vs. Accuracy Trade-Off}
]{name=costacc, column=1, between=row11 and row17}{
  \centering
  \includegraphics[width=0.98\linewidth]{figures/cost_vs_accuracy.pdf}\\[4mm]
  {\fontsize{22}{28}\selectfont\color{textgray}\textit{Cost varies 23$\times$ — top performance does not require top spend.}}
}

\posterbox[tealcard, title={Key Takeaways}
]{name=takeaways, column=1, between=row17 and bottom}{
  \fontsize{26}{34}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item {\color{primary}\bfseries GPT-5 (high)} leads at 88.0\% accuracy at premium cost
    \item {\color{secondary}\bfseries Claude 4.0} models offer best accuracy--reliability balance
    \item {\color{accent}\bfseries DeepSeek \& Gemini} deliver strong value at \$$<$5
    \item {\color{primary}\bfseries diff-fenced} format yields higher compliance (93--97\%)
    \item Models under \$5 still exceed 70\% accuracy — viable for many tasks
  \end{itemize}
}

% ══════════════════════════════════════════════════════════════
% COLUMN 2-3: MODEL RANKING CHART (rows 7-15) — THE CENTERPIECE
% ══════════════════════════════════════════════════════════════
\posterbox[highlightcard, title={Top Models by Accuracy — Ranked}
]{name=ranking, column=2, span=2, between=row7 and row14}{
  \centering\vspace{-4pt}
  \includegraphics[width=0.98\linewidth]{figures/model_ranking.pdf}\\[2mm]
  {\fontsize{22}{28}\selectfont\color{textgray}\textit{Bar colors indicate model family. Cost (\$) shown below each model name.}}
}

% ══════════════════════════════════════════════════════════════
% COLUMN 2-3: EDIT FORMAT COMPLIANCE (rows 14-20)
% ══════════════════════════════════════════════════════════════
\posterbox[tealcard, title={Edit Format Compliance}
]{name=format, column=2, span=2, between=row14 and bottom}{
  \centering\vspace{-6pt}
  \includegraphics[width=0.96\linewidth]{figures/edit_format.pdf}\\[2mm]
  {\fontsize{22}{28}\selectfont\color{textgray}\textit{diff-fenced models (teal) consistently outperform plain diff models (blue) in format reliability.}}
}

\end{tcbposter}
\end{document}

